 function positive(v){const n=Fin.cents(v);if(n<=0)throw Error('金额需大于 0');return n;}
 function checkDate(d){if(!Fin.validDate(d)||d>today())throw Error('请选择有效日期，不能晚于今天');}
 function addEntry(){addTx();}
 function addAsset(config={}){if(!config||config instanceof Element)config={};const initial=config.kind||'cash';form('登记资产',`<div class="fields"><div><label>类型</label><select name="kind">${Object.entries(meta).map(([k,m])=>`<option value="${k}" ${k===initial?'selected':''}>${m[0]}</option>`).join('')}</select></div><div><label>资产名称</label><input name="name" maxlength="50" placeholder="例如：工资卡" required></div></div><label id="asset-value-label">初始余额（元）</label><input name="value" inputmode="decimal" placeholder="0.00" required>${dateField('date',config.date||today(),'初始盘点日期')}<p class="disclosure" id="asset-boundary">填写当天后续记账前的余额。</p>${more('更多资料（可选）',`<label>存放平台 / 地点</label><input name="place" maxlength="80" placeholder="例如：支付宝"><div id="asset-risk"><label>风险标签（个人记录）</label><select name="risk">${['未知 / 未评估','低风险','中低风险','中风险','中高风险','高风险'].map(r=>`<option>${r}</option>`).join('')}</select></div><div id="asset-cost"><label>购入成本（元，可选）</label><input name="cost" inputmode="decimal" placeholder="0.00"></div>`)}`,d=>{checkDate(d.date);if(config.kind&&d.kind!==config.kind)throw Error('请先登记'+meta[config.kind][0]+'，再继续原操作');const value=Fin.cents(d.value),cost=d.cost?Fin.cents(d.cost):0;if(value<0||cost<0)throw Error('金额不能为负');change(s=>s.assets.push({id:uid(),name:d.name.trim(),kind:d.kind,place:(d.place||'').trim(),risk:d.risk||'未知 / 未评估',cost,snapshots:[{date:d.date,value,confirmed:false,opening:true}]}));return config.next;},'保存资产');const update=()=>{const k=$('field-kind').value;$('asset-value-label').textContent={cash:'初始余额（元）',investment:'初始投资价值（元）',item:'预计变现净残值（元）',debt:'当前欠款（元）'}[k];$('asset-boundary').textContent=k==='item'?'残值请扣除预计交易费用，成本不会重复计入财富。':'填写当天后续记账前的金额，不据此推算更早收益。';toggleFields('#asset-risk',k==='investment');toggleFields('#asset-cost',k==='item');};$('field-kind').addEventListener('change',update);update();}
