   const enabled=[...select.options].filter(o=>!o.disabled),simple=['income','expense'].includes(type),canSave=type==='transfer'?as.length>=2:enabled.length>0;f.querySelector('[type="submit"]').disabled=!canSave;$('tx-missing').hidden=canSave;
