 function setTxField(name,value){const field=$('field-'+name);field.value=value;field.dispatchEvent(new Event('change'));}
 function editAsset(aid){const a=state.assets.find(a=>a.id===aid);form('编辑资产资料',`<label>资产名称</label><input name="name" maxlength="50" value="${esc(a?.name||'仅记收支')}" required><label>存放平台 / 地点</label><input name="place" maxlength="80" value="${esc(a.place)}">${a.kind==='investment'?`<label>风险标签（个人记录）</label><select name="risk">${['未知 / 未评估','低风险','中低风险','中风险','中高风险','高风险'].map(r=>`<option ${r===a.risk?'selected':''}>${r}</option>`).join('')}</select>`:''}${a.kind==='item'?`<label>购入成本（元）</label><input name="cost" inputmode="decimal" value="${((a.cost||0)/100).toFixed(2)}" required>`:''}`,d=>change(s=>{const x=s.assets.find(a=>a.id===aid);x.name=d.name.trim();x.place=d.place.trim();if(d.risk)x.risk=d.risk;if(d.cost!==undefined){x.cost=Fin.cents(d.cost);if(x.cost<0)throw Error('成本不能为负');}}),'保存资料');}
 function detail(aid){const a=state.assets.find(a=>a.id===aid);if(!a)return;const p=Fin.performance(state,a),snaps=[...a.snapshots].sort((x,y)=>y.date.localeCompare(x.date));modal(a.name,`<div class="muted">${meta[a.kind][0]} · ${esc(a.place||'未填写位置')}${a.kind==='investment'?' · '+esc(a.risk):''}${a.sold?' · 已出售':''}</div><div class="detail-value">¥ ${money(Fin.balance(state,a,today()))}</div>${!a.sold?`<div class="form-actions">${btn('snapshot','更新'+(a.kind==='item'?'残值':a.kind==='debt'?'欠款':'余额'),'primary',`data-id="${esc(a.id)}"`)}${a.kind==='item'?btn('sell','出售登记','secondary',`data-id="${esc(a.id)}"`):''}</div>`:''}${p?`<div class="detail-grid"><div><small>${p.complete?'区间收益':'余额变化（未核验）'}</small><strong>¥ ${money(p.complete?p.gain:p.last.value-p.first.value)}</strong></div><div><small>${p.rate===null?'历史年化 · XIRR':'持有期收益率'}</small><strong>${pct(p.rate===null?p.annual:p.rate)}</strong></div></div><p class="disclosure">${p.first.date} → ${p.last.date} · ${p.complete?'已扣除净投入，年化不代表未来收益。':'现金流未核验完整，收益率不可计算。'}</p>${more('收益计算依据',`<p>历史年化 · XIRR：${p.annual===null?'不可计算':pct(p.annual)}</p><p>持有期收益率：${p.rate===null?'不可计算（存在现金流或数据不足）':pct(p.rate)}</p><p class="disclosure">区间 ${p.days} 天。无解、非唯一解或数据不足时不展示确定的收益率。</p>`)}`:''}${a.kind==='item'?`<p class="muted">购入成本 ¥ ${money(a.cost||0)} · 残值变化 ¥ ${money(Fin.balance(state,a,today())-(a.cost||0))}</p><p class="disclosure">残值为手工估计，并非平台报价。</p>`:''}${more('估值历史 · '+snaps.length+' 条',`${snaps.map((v,i)=>`<div class="row"><div class="row-main"><h3>${v.date}</h3><span class="muted">${v.opening?'初始盘点（记账前）':v.confirmed?'日末 · 已核验':'日末 · 未核验'}</span></div><div class="row-right"><div class="money">¥ ${money(v.value)}</div>${i<snaps.length-1&&!a.sold?btn('remove-snapshot','删除','text-button danger',`data-id="${esc(a.id)}" data-date="${v.date}"`):''}</div></div>`).join('')}`)}${more('资产管理',`${btn('edit-asset','编辑资料','secondary',`data-id="${esc(a.id)}"`)} ${btn('delete-asset','删除资产','text-button danger',`data-id="${esc(a.id)}"`)}`)}`);}
 function snapshot(aid){const a=state.assets.find(a=>a.id===aid);if(a.sold)return toast('已售物品不能再更新残值');form('定期总结 · '+a.name,`${dateField()}<label>当天结束时金额（元）</label><input name="value" inputmode="decimal" required value="${(Fin.balance(state,a,today())/100).toFixed(2)}">${a.kind==='investment'?'<div id="balance-review" class="disclosure" aria-live="polite"></div><label>期间是否有额外投入、取出或分红？</label><select name="review" required><option value="">请选择核对结果</option><option value="none">没有资金进出</option><option value="recorded">有，且已全部记账</option><option value="missing">有，需补记 / 暂不确定</option></select><p class="disclosure">需补记时先保存余额，再通过记一笔登记追加、取出或转账，之后重新更新余额核验。</p>':''}<div class="callout">同日估值将被替换。同日流水视为已包含在金额中；之后日期的流水才会继续影响余额。</div>`,d=>{checkDate(d.date);const first=[...a.snapshots].sort((x,y)=>x.date.localeCompare(y.date))[0];if(d.date<first.date)throw Error('不能早于初始盘点');const value=Fin.cents(d.value);if(value<0)throw Error('金额不能为负');if(a.kind==='investment'&&d.date<=first.date)throw Error('总结日期需晚于初始盘点');if(d.review==='none'&&Fin.snapshotReview(state,a,d.date,value).hasFlows)throw Error('期间已有资金进出，请核对后选择已全部记账');d.confirmed=['none','recorded'].includes(d.review);change(s=>{const x=s.assets.find(x=>x.id===aid),v=x.snapshots.find(v=>v.date===d.date);if(v){v.value=value;v.confirmed=!!d.confirmed;v.opening=false;}else x.snapshots.push({date:d.date,value,confirmed:!!d.confirmed});x.snapshots.filter(v=>v.date>d.date).forEach(v=>v.confirmed=false);});},'保存总结');if(a.kind==='investment'){const update=()=>{try{const r=Fin.snapshotReview(state,a,$('field-date').value,Fin.cents($('field-value').value));$('balance-review').textContent=r.unusual?'余额变化较大：是否有额外投入（含定投）、取出或分红？请核对。':'核对期间资金进出后计算收益，余额增加本身不等于收益。';}catch(e){$('balance-review').textContent='请输入有效日期和金额';}};['date','value'].forEach(k=>$('field-'+k).addEventListener('input',update));update();}}
 function confirm(title,text,fn){modal(title,`<div class="callout">${text}</div><div class="form-actions">${btn('close','取消','secondary')}<button type="button" id="confirm-action" class="primary">确认</button></div>`);$('confirm-action').onclick=()=>{try{fn();close();toast('操作完成');}catch(e){toast(e.message);}};}
 function sell(aid){const a=state.assets.find(a=>a.id===aid),cash=state.assets.filter(a=>a.kind==='cash');if(!cash.length)return toast('请先登记用于收款的现金账户');form('出售 · '+a.name,`<label>实际到账净额（元）</label><input name="amount" inputmode="decimal" required placeholder="扣除运费及手续费"><label>到账账户</label><select name="account">${options(cash)}</select>${dateField()}<div class="callout">按出售日将实物残值归零，并记一笔到账收入。保留物品历史。</div>`,d=>{checkDate(d.date);const amount=positive(d.amount),last=[...a.snapshots].sort((x,y)=>x.date.localeCompare(y.date)).at(-1);if(d.date<last.date)throw Error('出售日期不能早于最新估值');if(a.sold)throw Error('此物品已经出售');change(s=>{const x=s.assets.find(x=>x.id===aid);x.snapshots=x.snapshots.filter(v=>v.date!==d.date);x.snapshots.push({date:d.date,value:0,confirmed:true});const tid=uid();x.sold=tid;s.transactions.push({id:tid,type:'income',asset:d.account,to:null,amount,date:d.date,note:'出售：'+a.name});});});}

 let updateView=false,updateTimer,updateLast="";
 function updates(){updateView=true;updateLast="";$('modal-title').textContent="应用更新";updateStatus(typeof DeviceUpdater==='undefined'?{current:'0.1.13',phase:'browser',message:'请在安卓应用中检测和下载更新。'}:JSON.parse(DeviceUpdater.status()));clearInterval(updateTimer);if(typeof DeviceUpdater!=='undefined')updateTimer=setInterval(()=>{if(!$('modal').open||$('modal-title').textContent!=='应用更新'){clearInterval(updateTimer);updateView=false;return;}updateStatus(JSON.parse(DeviceUpdater.status()));},1000);}
 function updateStatus(s){if(!updateView||($('modal').open&&$('modal-title').textContent!=='应用更新'))return;const serialized=JSON.stringify(s);if(serialized===updateLast)return;updateLast=serialized;const r=s.release,busy=['checking','downloading','verifying'].includes(s.phase),percent=s.total?Math.min(100,Math.floor(s.downloaded/s.total*100)):0;modal('应用更新',`<p class="muted">当前版本 ${esc(s.current)} · GitHub Release</p><div class="callout" role="status">${esc(s.message)}</div>${r?`<h3>新版本 ${esc(r.version)}</h3><p class="muted">安装包 ${(r.size/1048576).toFixed(1)} MB</p>`:''}${['downloading','paused','verifying'].includes(s.phase)&&s.total?`<progress max="100" value="${percent}" aria-label="下载进度"></progress><p class="muted">${percent}% · ${(s.downloaded/1048576).toFixed(1)} / ${(s.total/1048576).toFixed(1)} MB</p>`:''}<div class="backup-buttons">${s.phase==='browser'?'':s.phase==='ready'?btn('update-install','安装更新'):s.phase==='downloading'?btn('update-pause','暂停下载'):!busy&&r&&s.phase!=='latest'?btn('update-download',s.downloaded?'继续下载':'下载更新'):''}${!busy&&s.phase!=='browser'?btn('update-check','检测更新','secondary'):''}${s.phase!=='browser'?btn('update-release','查看 GitHub Release','text-button'):'<a href="https://github.com/tyrantqiao/SquirrelFin/releases" target="_blank" rel="noopener">查看 GitHub Release</a>'}</div><p class="disclosure">仅检测和下载更新时联网，不上传账本。下载可断点继续；安装前核验 SHA-256、包名、版本与签名，由系统确认安装。开发签名包仅供试用。</p>${r?.notes?`<section class="inline-help"><h3>更新说明</h3><p class="release-notes">${esc(r.notes)}</p></section>`:''}`);}
 function settings(){modal('数据与备份',`<div class="callout">数据只保存在当前${native?'设备应用私有目录':'浏览器'}。${native?'卸载应用':'清除浏览器数据'}会删除记录，请定期导出。备份为明文 JSON，请妥善保存。</div><div class="backup-buttons">${btn('updates','应用更新','secondary')}${btn('export','↓ 导出完整备份')}${btn('import','↑ 从备份恢复','secondary')}${btn('clear','清空全部数据','secondary danger')}</div><div class="disclosure">0.1.13 · 无登录、无服务器、无交易功能。备份恢复将替换当前记录，建议先导出。金额隐藏仅遮挡界面，不是应用锁。</div>`);}
 function importText(text){try{if(text.length>5000000)throw Error('文件过大');const next=Fin.validate(JSON.parse(text));confirm('恢复本地备份',`包含 ${next.assets.length} 项资产、${next.transactions.length} 笔流水。确认后替换全部当前记录。`,()=>persist(next));}catch(e){toast('恢复失败：'+e.message);}}
 function exportData(){if(storageError)return toast('本地读取失败，不能导出空备份');const json=JSON.stringify(state,null,2);if(native)LocalDevice.exportBackup(json);else{const url=URL.createObjectURL(new Blob([json],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='SquirrelFin-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已生成');}}
 function ledgerImportText(){
  form('导入记账',`<p class="muted">粘贴文字账单，先预览，再保存。</p><label>账单文字</label><textarea name="ledgerText" rows="9" maxlength="150000" required placeholder="2026-09-01 支出❌ 日常 早餐 12">${esc(ledgerImportDraft.text)}</textarea><div class="import-file-action">${btn('ledger-file','选择 TXT / Markdown 文件','secondary')}</div><p class="disclosure">支持列表符号、表情和多余空格。格式：日期 收入/支出 原分类 备注 金额。</p><p class="disclosure">这是追加流水，不会替换账本。收入来源「投资」不会当作投资追加；默认仅在本地记录收支，不改变资产余额。</p>`,d=>{const parsed=Fin.parseLedgerText(d.ledgerText,today());ledgerImportDraft={text:d.ledgerText,...parsed};return()=>ledgerImportPreview();},'预览账单');
 }
 function importLedgerText(text){if(typeof text!=='string'||text.length>150000)return toast('账单文字最多 15 万字');ledgerImportDraft={text,rows:[],errors:[]};ledgerImportText();}
 function ledgerImportPreview(){
  const rows=ledgerImportDraft.rows,choice=(values,value)=>values.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
  form('核对导入账单',`
   <div class="toolbar"><span class="muted">识别 ${rows.length} 笔</span>${btn('ledger-import-edit','返回修改','text-button')}</div>
   <p class="disclosure">本地直接记收支，不绑定账户。已按原分类与备注预分类，可逐笔或批量调整。疑似重复默认不勾选。</p>
   <details class="import-batch"><summary>批量调整分类</summary><label>原分类范围</label><select name="batchSource"><option value="">全部支出</option>${choice([...new Set(rows.filter(r=>r.type==='expense').map(r=>r.sourceCategory))].map(c=>[c,c]),'')}</select><label>备注包含（可选）</label><input name="batchKeyword" placeholder="例如：房租、ChatGPT"><div class="fields"><div><label>改为用途</label><select name="batchCategory"><option value="">保持用途</option>${choice(Fin.expenseCategories.map(c=>[c,c]),'')}</select></div><div><label>改为性质</label><select name="batchNature"><option value="">保持性质</option>${choice(Object.entries(Fin.expenseNatures),'')}</select></div></div><button type="button" id="import-batch-apply" class="secondary">应用到匹配的已选支出</button><p id="import-batch-result" role="status"></p></details>
   <label>查看记录</label><select name="importView"><option value="all">全部记录</option><option value="other">待核对：其他分类</option><option value="duplicate">疑似重复</option></select>
   ${ledgerImportDraft.errors.length?`<div class="import-errors" role="alert">${ledgerImportDraft.errors.map(e=>`<p>第 ${e.line} 行：${esc(e.message)}</p>`).join('')}<p>请返回修改；有错误时不会导入任何一笔。</p></div>`:''}
   <div class="import-entries">${rows.map((r,i)=>`<section class="import-entry" data-index="${i}"><label class="import-row-select"><input type="checkbox" name="row${i}"><span class="row-main"><strong>${esc(r.note)}</strong><small>${r.date} · ${r.type==='income'?'收入':'支出'} · 原分类 ${esc(r.sourceCategory)}</small></span><span class="money">${r.type==='income'?'+':'−'}¥ ${money(r.amount)}</span></label><p class="import-row-status" role="status"></p>${r.type==='expense'?`<details class="import-adjust"><summary>调整分类</summary><div class="fields"><div><label>支出用途</label><select name="category${i}">${choice(Fin.expenseCategories.map(c=>[c,c]),r.category)}</select></div><div><label>支出性质</label><select name="nature${i}">${choice(Object.entries(Fin.expenseNatures),r.nature)}</select></div></div></details>`:''}</section>`).join('')}</div>
  `,d=>{
   if(ledgerImportDraft.errors.length)throw Error('请先返回修正格式错误');
   const selected=collect().filter((r,i)=>d['row'+i]);if(!selected.length)throw Error('请选择至少一笔有效账单');
   const next=Fin.importLedger(state,selected,today(),uid);page='ledger';ledgerDate=selected.map(r=>r.date).sort().at(-1);ledgerPeriod='month';ledgerFilter='all';persist(next);const count=selected.length;ledgerImportDraft={text:'',rows:[],errors:[]};return()=>toast('已导入 '+count+' 笔记账');
  },'确认导入');
  const f=$('entry-form'),submit=f.querySelector('[type="submit"]'),summary=document.createElement('p');summary.className='import-summary';f.querySelector('.submit-area').prepend(summary);
  const collect=()=>rows.map((r,i)=>({...r,asset:null,...(r.type==='expense'?{category:f.elements.namedItem('category'+i).value,nature:f.elements.namedItem('nature'+i).value}:{})}));
  const update=()=>{
   const preview=Fin.ledgerImportPreview(state,collect(),today());let income=0,expense=0,count=0,duplicates=0;
   preview.forEach((r,i)=>{const entry=f.querySelector('[data-index="'+i+'"]'),box=f.elements.namedItem('row'+i);box.disabled=!!r.error;if(!box.dataset.manual)box.checked=!r.error&&!r.duplicate;if(r.error)box.checked=false;entry.querySelector('.import-row-status').textContent=r.error||((r.duplicate?'疑似重复 · ':'')+(r.type==='expense'?r.category+' · '+Fin.expenseNatures[r.nature]: '收入来源：'+r.sourceCategory));entry.hidden=f.elements.importView.value==='other'&&r.category!=='其他'||f.elements.importView.value==='duplicate'&&!r.duplicate;entry.classList.toggle('has-error',!!r.error);entry.classList.toggle('is-duplicate',r.duplicate);if(box.checked){count++;if(r.type==='income')income+=r.amount;else expense+=r.amount;if(r.duplicate)duplicates++;}});
   summary.textContent='已选 '+count+' 笔 · 收入 ¥ '+money(income)+' · 支出 ¥ '+money(expense)+(duplicates?' · 含 '+duplicates+' 笔重复候选':'');submit.textContent='确认导入 '+count+' 笔';submit.disabled=!count||!!ledgerImportDraft.errors.length;
  };
  $('import-batch-apply').onclick=()=>{const source=f.elements.batchSource.value,keyword=f.elements.batchKeyword.value.trim().toLowerCase(),category=f.elements.batchCategory.value,nature=f.elements.batchNature.value;let count=0;if(!category&&!nature){$('import-batch-result').textContent='请先选择用途或性质';return;}rows.forEach((r,i)=>{if(r.type!=='expense'||!f.elements.namedItem('row'+i).checked||(source&&r.sourceCategory!==source)||(keyword&&!r.note.toLowerCase().includes(keyword)))return;if(category)f.elements.namedItem('category'+i).value=category;if(nature)f.elements.namedItem('nature'+i).value=nature;count++;});update();$('import-batch-result').textContent='已调整 '+count+' 笔，可展开逐笔修改检查';};
  f.addEventListener('change',e=>{if(e.target.type==='checkbox')e.target.dataset.manual='1';update();});update();
 }

 const actions={updates:updates,'update-check':()=>DeviceUpdater.check(),'update-download':()=>DeviceUpdater.download(),'update-pause':()=>DeviceUpdater.pause(),'update-install':()=>DeviceUpdater.install(),'update-release':()=>DeviceUpdater.openRelease(),nav:e=>{page=e.dataset.page;render();},filter:e=>{filter=e.dataset.filter;render();},'ledger-import':()=>ledgerImportText(),'ledger-import-edit':()=>ledgerImportText(),'ledger-file':()=>native?LocalDevice.importLedger():$('ledger-file').click(),'today-ledger':todayLedger,'add-entry':()=>addEntry(),'add-asset':()=>addAsset(),'add-tx':()=>addTx(),'tx-type':e=>setTxField('type',e.dataset.type),'tx-category':e=>setTxField('category',e.dataset.category),'tx-nature':e=>setTxField('nature',e.dataset.nature),'tx-clear':()=>{$('field-amount').value='';$('field-amount').focus();},'edit-tx':e=>addTx({edit:e.dataset.id}),'tx-detail':e=>txDetail(e.dataset.id),'ledger-view':e=>{ledgerView=e.dataset.view;render();},'report-drill':reportDrill,'ledger-period':e=>{ledgerPeriod=e.dataset.period;render();},'ledger-filter':e=>{ledgerFilter=e.dataset.filter;render();},'use-template':e=>addTx({template:e.dataset.id}),'delete-template':e=>confirm('删除常用模板','仅删除模板，已记支出保留。',()=>change(s=>s.expenseTemplates=s.expenseTemplates.filter(t=>t.id!==e.dataset.id))),detail:e=>detail(e.dataset.id),'edit-asset':e=>editAsset(e.dataset.id),snapshot:e=>snapshot(e.dataset.id),sell:e=>sell(e.dataset.id),close,export:exportData,import:()=>native?LocalDevice.importBackup():$('import-file').click(),clear:()=>confirm('清空本地数据','全部资产与流水记录都会删除，无法撤销。请先导出备份。',()=>persist(Fin.blank())), 'delete-asset':e=>{const aid=e.dataset.id;if((state.expenseTemplates||[]).some(t=>t.asset===aid)||state.transactions.some(t=>t.asset===aid||t.to===aid)||state.plans.some(p=>p.asset===aid)||state.assets.find(a=>a.id===aid).sold)return toast('请先处理关联流水、常用模板、计划或出售记录');confirm('删除资产','该资产及全部估值历史将删除。',()=>change(s=>s.assets=s.assets.filter(a=>a.id!==aid)));},'delete-tx':e=>{if(state.assets.some(a=>a.sold===e.dataset.id))return toast('出售到账记录需要保留，以维持实物与资金一致');confirm('删除流水','余额和收益重新计算；关联的投入和转出会一起删除。',()=>change(s=>{const tx=s.transactions.find(t=>t.id===e.dataset.id),ex=s.executions.find(x=>x.transaction===tx.id||x.sourceTransaction===tx.id),ids=new Set([tx.id]);if(ex){if(ex.transaction)ids.add(ex.transaction);if(ex.sourceTransaction)ids.add(ex.sourceTransaction);}s.transactions.forEach(t=>{if(t.linked===tx.id)ids.add(t.id);if(tx.linked)ids.add(tx.linked);});s.transactions.filter(t=>ids.has(t.id)).forEach(t=>invalidate(s,t));s.transactions=s.transactions.filter(t=>!ids.has(t.id));s.executions=s.executions.filter(x=>!ids.has(x.transaction)&&!ids.has(x.sourceTransaction));}));},'remove-snapshot':e=>confirm('删除估值','使用较早估值与后续流水重新计算，后续投资估值需重新核验。',()=>change(s=>{const a=s.assets.find(a=>a.id===e.dataset.id);if(a.sold)throw Error('已售物品估值不能删除');a.snapshots=a.snapshots.filter(v=>v.date!==e.dataset.date);a.snapshots.filter(v=>v.date>e.dataset.date).forEach(v=>v.confirmed=false);} ))};
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();try{if(storageError&&!['close','clear','import'].includes(el.dataset.action))return toast('本地数据读取失败，请先恢复备份或明确清空');actions[el.dataset.action]?.(el);}catch(err){toast(err.message);}});
